def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    ls = len(s)

    def count(n):
        # number of powerful integers in [1, n]: end with suffix s, every digit <= limit
        ns = str(n)
        if len(ns) < ls:
            return 0
        if len(ns) == ls:
            return 1 if int(s) <= n else 0
        prefix = ns[:len(ns) - ls]      # the free leading part
        res = 0
        for i, ch in enumerate(prefix):
            d = int(ch)
            if d > limit:
                # every remaining prefix digit may be 0..limit freely
                return res + (limit + 1) ** (len(prefix) - i)
            res += d * (limit + 1) ** (len(prefix) - 1 - i)
        # all prefix digits were <= limit; the suffix must be >= s to stay <= n
        if int(ns[len(ns) - ls:]) >= int(s):
            res += 1
        return res

    return count(finish) - count(start - 1)
